{
    uint8 secLvlIdx = DCM_2741_SCURITYLEVEL_INDEX;
    uint8 ret = DCM_E_OK;

    Dcm_27_Security_Data[secLvlIdx].AttemptCounter = AttemptCounter;
    DCM_DUMMY_STATEMENT(OpStatus);

    return ret;
}
